#!/usr/bin/env bash
# Copyright (c) PRO-Robotech
# SPDX-License-Identifier: BUSL-1.1
#
# ЕДИНСТВЕННЫЙ ВЛАДЕЛЕЦ подъёма стенда в конвейере: поднимает и НАЗЫВАЕТ КАТЕГОРИЮ
# ИСХОДА — зелено · красное · «не выполнилось».
#
# ─────────────────────────────────────────────────────────────────────────────
# ПРЕДМЕТ (kacho#2250)
#
# Различение трёх исходов заведено в этом дереве намеренно: 0 — зелено, 1 —
# находка о дереве, 3 — прогон недействителен, вердикта нет ни у одной проверки.
# Владелец материализации зависимостей умбреллы (deploy/scripts/helm-umbrella-deps.sh)
# третий исход ПРОИЗВОДИТ: он различает отказ НАШ и отказ ЧУЖОЙ по строке, которую
# печатает сам helm, и на чужом выходит кодом 3.
#
# Код 3 через `make` НЕ ПРОХОДИТ by construction: make отвечает своей двойкой на
# любой упавший рецепт. Поэтому причина едет ОТМЕТКОЙ-файлом, которую владелец
# материализации кладёт и снимает в начале каждого своего прогона.
#
# ОТМЕТКУ ЧИТАЛ ОДИН ИЗ ЧЕТЫРЁХ. Замер по дереву на f9a04a5ef (предикат —
# `assert-stand-precondition-wiring.py`, он же гейт): шагов конвейера, поднимающих
# стенд, ЧЕТЫРЕ; отметку читал ОДИН (шард сквозного прогона). Остальные три —
# боевая посадка, консоль и материализация в проверке чартов — отдавали шагу
# двойку make, и работа краснела. Наблюдалось на прогоне 34147256284: посторонний
# источник чартов оборвал соединение, наш механизм отработал верно и напечатал
# «отказ ЧУЖОЙ», а до сводки доехало обычное красное — то есть линия получила
# «регрессию» по причине, к дереву отношения не имеющей.
#
# ─────────────────────────────────────────────────────────────────────────────
# ЧТО ЗДЕСЬ РЕШЕНО, И ЧТО ЭТО ОТМЕНЯЕТ
#
# «НЕ ВЫПОЛНИЛОСЬ» БОЛЬШЕ НЕ КРАСИТ РАБОТУ (решение владельца 2026-09-07, #2250).
# Прежняя редакция шага шарда объявляла обратное — «шаг остаётся красным, и это
# намеренно», — и довод был: третьего цвета у работы конвейера нет, а «не
# выполнилось» не идёт в зачёт «прошло». Довод верен ровно наполовину, и вторая
# половина дороже: пока чужая недоступность красит работу, условие «прогон зелен
# целиком» зависит от доступности постороннего хоста, то есть недостижимо by
# construction. Ждать зелёного там, где его производит не наше дерево, — значит
# не иметь предиката готовности вовсе.
#
# Поэтому цвет работы теперь означает ровно одно: «дерево судили, и вот вердикт».
# Отсутствие вердикта цветом не выражается — оно выражается СЛОВОМ, и слово это
# печатается туда, куда смотрит читатель сводки: отдельной строкой сводки прогона
# и аннотацией.
#
# ОСТАТОК, НАЗВАННЫЙ ЗДЕСЬ 2026-09-07, ВЛАДЕЛЬЦЕМ ОТМЕНЁН 2026-09-12. Здесь стояло:
# «проверка в списке запроса на слияние станет ЗЕЛЁНОЙ, а зелёная проверка означает
# „слиянию не препятствует“, НЕ „стенд поднялся“». Остаток оказался дороже своего
# довода: зелёный кружок читается как гарантия, и отличить «проверено, замечаний нет»
# от «мы не спрашивали» читатель сводки не мог. Замер на прогонах 34694955300 и
# 34694955309: консоль вышла `success`, пропустив прогон проб и гейт по отчёту;
# четыре шарда вышли `success` при НУЛЕ исполненных коллекций из 57.
#
# Решение владельца 2026-09-12, дословно: «сделай так, чтобы можно было гарантировать
# зелёный; если что-то не так — в красный». ЭТОТ СКРИПТ ОТ ТОГО НЕ ИЗМЕНИЛСЯ: он
# по-прежнему выходит нулём на третьей категории и по-прежнему НЕ красит свой шаг —
# красноту производит ОТДЕЛЬНЫЙ ВЛАДЕЛЕЦ, последний шаг работы
# (`.github/scripts/assert-declared-verdicts-ran.py`): он сверяет объявленные
# вердиктные шаги с исполненными и роняет работу, когда объявленное результата не
# дало. Различение трёх категорий осталось СЛОВОМ — в сводке, в аннотации и в тексте
# того отказа; цветом теперь выражается только «вердикт есть или его нет».
#
# Почему разными владельцами: причину наблюдает ТОЛЬКО тот, кто поднимал стенд, а
# полноту вердикта — только тот, кто видит исходы ВСЕХ шагов работы. Сведя их в один
# шаг, мы получили бы шаг, роняющий работу раньше, чем станет известно, чего в ней не
# хватило.
#
# Само послабление — НЕ маска и не `continue-on-error`:
#   · послабление выдаётся ТОЛЬКО под доказательство — отметку, которую кладёт
#     тот, кто НАБЛЮДАЛ чужую недоступность, и только он;
#   · отметка снимается в начале каждого прогона материализации, поэтому пережить
#     свой предмет не может;
#   · отказ без отметки остаётся красным дословно как прежде — и это законный
#     близнец, без которого правка превратила бы любой срыв подъёма в «условие не
#     создано».
# Предмет самой чужой зависимости (13 объявлений с 4 посторонних хостов) снимается
# отдельной работой — kacho#2256; до неё третья категория остаётся достижимой.
#
# ─────────────────────────────────────────────────────────────────────────────
# ПОЧЕМУ ЛОГИКА ЗДЕСЬ, А НЕ В ТЕЛЕ ШАГА
#
# 1. Тело шага исполняется под `bash -e` (`defaults.run.shell: bash` — это
#    `bash --noprofile --norc -eo pipefail`). Ненулевой код обрывает тело МОЛЧА,
#    не дойдя до развилки: `-e` не освобождает простую команду. Поэтому код
#    возврата берётся ВЕЛИЧИНОЙ (`cmd && rc=0 || rc=$?`), а не условием
#    продолжения, — и это единственная форма, при которой развилка вообще
#    исполняется.
# 2. Логику в YAML нельзя прогнать. Здесь она прогоняется: `--self-test`
#    запускает НАСТОЯЩИЙ этот скрипт под теми же флагами оболочки, подменяя ровно
#    два факта — команду подъёма и наличие отметки, — и требует предсказанного
#    исхода по каждому из трёх случаев плюс по законному близнецу.
# 3. Четыре копии развилки в четырёх работах разошлись бы молча. Они уже
#    разошлись: у трёх её не было вовсе.
#
# ─────────────────────────────────────────────────────────────────────────────
# Использование:
#   .github/scripts/stand-up.sh --label "<что поднимаем>" [--dir <каталог>] -- <команда...>
#   .github/scripts/stand-up.sh --self-test
#
# Коды возврата:
#   0 — зелено (стенд поднялся) ЛИБО «не выполнилось» (чужая недоступность
#       ДОКАЗАНА отметкой). Различает их не код, а напечатанная категория;
#   код команды — красное: подъём сорвался, доказательства чужой причины нет;
#   2 — предпосылки самого скрипта не выполнены (не назван ярлык или команда).
#
# Что кладётся вызывающему:
#   $GITHUB_ENV     STAND_PRECONDITION_UNMET=1  — шаги ниже обязаны на нём пропускаться;
#   $GITHUB_OUTPUT  category=green|unmet|red    — для разметчика исхода работы;
#   $GITHUB_STEP_SUMMARY — отдельная строка категории и перепись тремя числами.
set -uo pipefail

MARK_NAME=".kacho-deps-precondition-unmet"
# Отметку кладёт ЕДИНСТВЕННЫЙ владелец материализации зависимостей умбреллы
# (deploy/scripts/helm-umbrella-deps.sh) — он и только он наблюдает чужую
# недоступность. Путь берётся от корня рабочего дерева: в конвейере это
# GITHUB_WORKSPACE, вне его — корень репозитория от расположения скрипта.
# Переменная та же, что у конвейера, поэтому самопроверка подменяет РЕАЛЬНЫЙ
# факт, а не заводит собственную ручку.
ROOT="${GITHUB_WORKSPACE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"
MARK="$ROOT/deploy/helm/umbrella/$MARK_NAME"

LABEL=""
DIR=""
SELFTEST=0

while [ $# -gt 0 ]; do
  case "$1" in
    --self-test) SELFTEST=1; shift ;;
    --label)     LABEL="${2:-}"; shift 2 ;;
    --dir)       DIR="${2:-}";   shift 2 ;;
    --)          shift; break ;;
    *)           echo "FATAL: неизвестный ключ '$1'"; exit 2 ;;
  esac
done

# ─────────────────────────────────────────────────────────────────────────────
# ВЫВОД: журнал · сводка прогона · аннотация. Три разных читателя, и путать их
# нельзя: журнал читает тот, кто уже пришёл разбираться, сводку — тот, кто ещё
# решает, идти ли, а аннотация — единственное, что доезжает до списка проверок
# запроса на слияние.
summary() { [ -n "${GITHUB_STEP_SUMMARY:-}" ] && printf '%s\n' "$*" >> "$GITHUB_STEP_SUMMARY"; return 0; }

# ПЕРЕПИСЬ ПЕЧАТАЕТ ТРИ ЧИСЛА, А НЕ ОДНО. Одно число («отказов 0») не отличает
# «дерево судили и оно чисто» от «судить не начинали»: обе величины дают ноль
# красных. Поэтому недействительные считаются ОТДЕЛЬНО и никогда не вычитаются
# из вердикта и не зачитываются в успех.
census() { # зелёных красных недействительных
  echo "перепись подъёма: зелёных $1 · красных $2 · недействительных $3"
  summary ""
  summary "| исход подъёма | сколько |"
  summary "|---|---|"
  summary "| зелёных | $1 |"
  summary "| красных | $2 |"
  summary "| недействительных («не выполнилось») | $3 |"
}

# ─────────────────────────────────────────────────────────────────────────────
# САМОПРОВЕРКА. Прогоняется НАСТОЯЩИЙ этот скрипт под той же оболочкой, что у
# конвейера, и подменяются ровно два факта: команда подъёма (её код возврата) и
# наличие отметки. Один факт на случай — иначе неизвестно, что дало исход.
if [ "$SELFTEST" = "1" ]; then
  ok=0
  SELF="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"
  echo "=== stand-up.sh --self-test ==="
  case_() { # ждём-код ждём-категорию ждём-флаг отметка код-команды метка [что печатает] [что обязано быть в журнале]
    local want_rc="$1" want_cat="$2" want_flag="$3" mark="$4" cmd_rc="$5" label="$6"
    local say="${7:-}" want_text="${8:-}"
    local d; d="$(mktemp -d)"
    mkdir -p "$d/deploy/helm/umbrella"
    printf '%s' "$say" > "$d/say"
    [ "$mark" = "есть" ] && printf 'источник чартов не ответил: https://charts.example.invalid/x\n' \
      > "$d/deploy/helm/umbrella/$MARK_NAME"
    : > "$d/env"; : > "$d/out"; : > "$d/sum"
    local got_rc=0
    # Та же оболочка, что у конвейера: `defaults.run.shell: bash` —
    # `bash --noprofile --norc -eo pipefail`. Под ней и обязана исполняться
    # развилка: если бы код возврата брался условием продолжения, тело
    # оборвалось бы здесь и ни один случай ниже не прошёл бы.
    GITHUB_WORKSPACE="$d" GITHUB_ENV="$d/env" GITHUB_OUTPUT="$d/out" GITHUB_STEP_SUMMARY="$d/sum" \
      bash --noprofile --norc -eo pipefail -c \
      "'$SELF' --label 'проба' -- sh -c 'cat $d/say 2>/dev/null; exit $cmd_rc'" >"$d/log" 2>&1 || got_rc=$?
    local got_cat got_flag=нет
    got_cat="$(sed -n 's/^category=//p' "$d/out" | tail -1)"
    grep -q 'STAND_PRECONDITION_UNMET=1' "$d/env" && got_flag=есть
    if [ "$got_rc" = "$want_rc" ] && [ "$got_cat" = "$want_cat" ] && [ "$got_flag" = "$want_flag" ]; then
      echo "  ОК  $label → код $got_rc, категория $got_cat, флаг $got_flag"
    else
      echo "  ПРОВАЛ $label → код $got_rc (ждали $want_rc), категория '$got_cat' (ждали '$want_cat'), флаг $got_flag (ждали $want_flag)"
      sed 's/^/        /' "$d/log" | tail -15
      ok=1
    fi
    if [ -n "$want_text" ] && ! grep -qF "$want_text" "$d/log"; then
      echo "  ПРОВАЛ $label → в журнале нет '$want_text'"; ok=1
    fi
    # Перепись обязана печатать ТРИ числа при любом исходе: одно число не
    # отличает «чисто» от «не читали».
    if ! grep -q 'перепись подъёма: зелёных .* красных .* недействительных ' "$d/log"; then
      echo "  ПРОВАЛ $label → перепись не напечатала три числа"; ok=1
    fi
    rm -rf "$d"
  }

  # (1) стенд поднялся — зелено, флага нет.
  case_ 0 green нет нет 0 'стенд поднялся'
  # (2) ТРЕТЬЯ КАТЕГОРИЯ: отметка ЕСТЬ (чужая недоступность доказана) → работа
  #     НЕ краснеет, категория названа, флаг выставлен.
  case_ 0 unmet есть есть 2 'чужой источник недоступен → «не выполнилось», работа не краснеет'
  # (3) ЗАКОННЫЙ БЛИЗНЕЦ: тот же срыв подъёма, отметки НЕТ → красное как прежде.
  #     Без этой половины правка превратила бы ЛЮБОЙ срыв в «условие не создано».
  case_ 2 red нет нет 2 'отказ без доказательства чужой причины → КРАСНОЕ'
  # (4) Код команды доезжает как есть, а не схлопывается в единицу: вызывающему
  #     нужен именно он, чтобы отличить make (2) от чего-то ещё.
  case_ 7 red нет нет 7 'код команды доезжает до шага как есть'
  # (5) Отметка ЛЕЖИТ, а стенд поднялся: до развилки дело не доходит вовсе —
  #     флаг не выставляется. (Снимает отметку её владелец, не мы.)
  case_ 0 green нет есть 0 'стенд поднялся при лежащей отметке → флага нет'

  # (6) ПРИЧИНА НАЗВАНА: вывод несёт признак «ранер не поднял узел kind».
  #     Категория обязана остаться КРАСНОЙ — понижения нет by construction, и
  #     это проверяется здесь, а не подразумевается.
  kindfail='ERROR: failed to create cluster: could not find a log line that matches "Reached target .*Multi-User System.*|detected cgroup v1"'
  # Искомое обязано отличать ветку от ЧУЖОГО ОБЪЯСНЕНИЯ: обобщающая ветка сама
  # называет эту фразу, говоря, что признака нет. Первая редакция искала
  # «ранер не поднял узел kind» и совпадала в ОБЕИХ ветках — то есть не
  # различала ничего; поймано инъекцией «признак не срабатывает никогда».
  case_ 1 red нет нет 1 'ранер не поднял узел kind → причина названа, категория красная' \
        "$kindfail" 'ПРИЧИНА НАЗВАНА: ранер не поднял узел kind'

  # (7) ЗАКОННЫЙ БЛИЗНЕЦ: тот же код возврата, тот же отсутствующий мар­кер, но
  #     признака в выводе НЕТ. Формулировка обязана остаться прежней — иначе
  #     признак ловил бы не себя, а любой срыв подъёма.
  case_ 1 red нет нет 1 'срыв без признака → прежняя формулировка' \
        'make: *** [Makefile:596: dev-up] Error 1' 'известные формы чужой причины НЕ доказаны'

  # (8) Половина признака — не признак. Кластер не создан, но фразы про
  #     недождавшийся узел нет: это ДРУГОЙ отказ, и называть его нашим именем
  #     нельзя.
  case_ 1 red нет нет 1 'половина признака не опознаётся как признак' \
        'ERROR: failed to create cluster: node image not present' 'известные формы чужой причины НЕ доказаны'

  # ── ВТОРАЯ ФОРМА ДОКАЗАТЕЛЬСТВА: ПРОКСИ МОДУЛЕЙ GO (#949) ────────────────
  #
  # Инъекция в обе стороны. Подменяется ровно один факт на случай — ВЫВОД
  # команды подъёма; отметки нет ни в одном из четырёх, то есть прежний путь
  # («доказательств чужой причины нет → красное») остаётся достижимым и
  # проверяется тут же.
  proxyfail='github.com/klauspost/compress@v1.19.1: Get "https://storage.googleapis.com/proxy-golang-org-prod/x": net/http: TLS handshake timeout
make: *** [Makefile:422: dev-up] Error 2'
  case_ 0 unmet есть нет 2 'прокси модулей Go не ответил транспортно → «не выполнилось»' \
        "$proxyfail" 'прокси модулей Go не ответил транспортно'

  # (11) ЗАКОННЫЙ БЛИЗНЕЦ: тот же хост, но отказ СОДЕРЖАТЕЛЬНЫЙ — это НАША
  #      поломка (неверный адрес модуля). Повтором не лечится, находкой быть не
  #      перестаёт.
  badpath='github.com/PRO-Robotech/нет-такого@v1.0.0: unrecognized import path "github.com/PRO-Robotech/нет-такого": parse https://proxy.golang.org/...: 404 Not Found
make: *** [Makefile:422: dev-up] Error 2'
  case_ 2 red нет нет 2 'неверный адрес модуля → по-прежнему НАХОДКА' \
        "$badpath" 'известные формы чужой причины НЕ доказаны'

  # (12) ЗАКОННЫЙ БЛИЗНЕЦ: отказ транспортный, но хост НЕ из перечня чужих —
  #      про наш собственный узел мы такого сказать не вправе.
  ourhost='Get "https://registry.internal.kacho/v2/": net/http: TLS handshake timeout
make: *** [Makefile:422: dev-up] Error 2'
  case_ 2 red нет нет 2 'транспортный отказ НЕ чужого хоста → находка' \
        "$ourhost" 'известные формы чужой причины НЕ доказаны'

  # (13) ВЕТО: оба признака на месте, но В ТОМ ЖЕ выводе есть содержательный
  #      отказ. Значит в прогоне ЕСТЬ находка о дереве, и снимать с неё цвет
  #      нельзя — даже если рядом действительно был сетевой шум.
  mixed='github.com/klauspost/compress@v1.19.1: Get "https://proxy.golang.org/x": net/http: TLS handshake timeout
verifying github.com/foo@v1.2.3: checksum mismatch
make: *** [Makefile:422: dev-up] Error 2'
  case_ 2 red нет нет 2 'сетевой шум рядом с содержательным отказом → находка' \
        "$mixed" 'известные формы чужой причины НЕ доказаны'

  # (9) ПРЕДПОСЫЛКИ СВОИ. Без ярлыка или без команды судить не о чем — и это
  #     код 2, отдельный от находки: «нечего делать» не есть «сделано».
  rc6=0; bash "$SELF" --label 'проба' -- >/dev/null 2>&1 || rc6=$?
  [ "$rc6" = "2" ] && echo "  ОК  без команды → код 2 (предпосылки не выполнены)" \
                   || { echo "  ПРОВАЛ без команды → код $rc6 (ждали 2)"; ok=1; }
  rc7=0; bash "$SELF" -- true >/dev/null 2>&1 || rc7=$?
  [ "$rc7" = "2" ] && echo "  ОК  без ярлыка → код 2" \
                   || { echo "  ПРОВАЛ без ярлыка → код $rc7 (ждали 2)"; ok=1; }

  echo "самопроверка: $([ $ok -eq 0 ] && echo PASS || echo FAIL)"
  exit $ok
fi

# ─────────────────────────────────────────────────────────────────────────────
[ -n "$LABEL" ] || { echo "FATAL: не назван --label — исход некому приписать"; exit 2; }
[ $# -gt 0 ] || { echo "FATAL: после -- нет команды подъёма — поднимать нечего"; exit 2; }

echo "=== $LABEL: подъём стенда"
echo "    команда: $*"
if [ -n "$DIR" ]; then
  cd "$DIR" || { echo "FATAL: нет каталога '$DIR'"; exit 2; }
fi

# КОД ВОЗВРАТА — ВЕЛИЧИНА, А НЕ УСЛОВИЕ ПРОДОЛЖЕНИЯ. Иначе `-e` оборвал бы
# скрипт здесь, до всякой развилки, и вся классификация ниже не исполнилась бы
# НИ РАЗУ — оставаясь при этом на вид написанной.
#
# ВЫВОД ЗАХВАТЫВАЕТСЯ, а не только печатается: по нему читается признак ниже.
# `tee` сохраняет поток читателю журнала слово в слово; код берётся из
# PIPESTATUS[0] — величины, которая называет код ИМЕННО подъёма и не зависит от
# того, включён ли `pipefail`.
#
# ЗДЕСЬ СТОЯЛО ЛОЖНОЕ УТВЕРЖДЕНИЕ, и снято оно замером, а не вычиткой: «подмени
# PIPESTATUS на $?, и самопроверка покраснеет». Инъекция показала обратное — под
# действующим `set -o pipefail` код конвейера равен коду подъёма, потому что
# `tee` возвращает ноль, и обе записи дают 7 на команде, вышедшей семёркой.
# То есть самопроверка эти две записи НЕ РАЗЛИЧАЕТ, и различать не обязана:
# PIPESTATUS выбран как точный, а не как единственный работающий. Снимут
# `pipefail` — разойдутся; сегодня нет.
STAND_LOG="$(mktemp)"
trap 'rm -f "$STAND_LOG"' EXIT
rc=0
"$@" 2>&1 | tee "$STAND_LOG"
rc="${PIPESTATUS[0]}"

echo "--- код возврата команды подъёма: $rc"

if [ "$rc" -eq 0 ]; then
  echo "категория: ЗЕЛЕНО — стенд поднялся"
  summary "### $LABEL — ЗЕЛЕНО"
  summary ""
  summary "Стенд поднялся; вердикт по нему выносят шаги ниже."
  census 1 0 0
  [ -n "${GITHUB_OUTPUT:-}" ] && echo "category=green" >> "$GITHUB_OUTPUT"
  exit 0
fi

# ─────────────────────────────────────────────────────────────────────────────
# ПРИЗНАК «РАНЕР НЕ МОЖЕТ ДЕРЖАТЬ KIND» (#2633)
#
# kind не смог поднять контейнер узла: тот не дошёл до многопользовательской
# цели. Фразу печатает САМ kind, а не мы. Кластера при этом не существовало ни
# секунды, значит ни один наш чарт, образ и миграция не исполнялись — разбирать
# дерево по такому отказу НЕ НАДО, и об этом надо сказать прямо в журнале.
#
# Наблюдалось 2026-09-13, шард nlb (#2626): `Preparing nodes` упал через 5.8 с
# после того, как образ узла тянулся 1 мин 53 с. На соседнем запросе #2630 тот же
# шард того же дерева — ЗЕЛЁНЫЙ. Значит свойство не дерева, а окружения: под
# меткой `ubuntu-latest` стоят два разных пула.
#
# ─── ПОЧЕМУ КАТЕГОРИЯ ВСЁ РАВНО ОСТАЁТСЯ КРАСНОЙ ────────────────────────────
#
# Соблазн — выдать третью категорию: вердикта о продукте и правда нет. Отказано
# намеренно. Послабление выдаётся под ДОКАЗАТЕЛЬСТВО чужой причины, а здесь
# доказательство было бы САМОСВИДЕТЕЛЬСТВОМ: признак читается из вывода той же
# команды, которую мы и судим, и сложенные ниже две части — «кластер не создан»
# и «узел не дошёл до цели» — суть один факт, записанный дважды, а не два
# независимых признака. Одного признака мало: ровно та же фраза выйдет, если
# МЫ запиним образ узла, несовместимый с ядром, — и тогда послабление скрыло бы
# нашу поломку навсегда, оставаясь на вид работающим.
#
# Форма, при которой понижение станет законным, названа и уже действует рядом:
# отметку кладёт тот, кто НАБЛЮДАЛ чужую недоступность, и это ДРУГОЙ владелец
# (см. MARK выше). Для хоста таким наблюдателем была бы отдельная проба
# способности машины держать systemd-контейнер — она независима от нашего
# подъёма и от нашего пина. Её здесь нет; заводится своим изменением.
#
# Поэтому шаг делает то, что может доказать: НАЗЫВАЕТ причину и печатает факты
# хоста, чтобы читатель адъюдицировал за один взгляд, а не за прогон.
host_cannot_host_kind() {
  [ -s "$STAND_LOG" ] || return 1
  grep -qF 'failed to create cluster' "$STAND_LOG" || return 1
  grep -qF 'could not find a log line that matches' "$STAND_LOG" || return 1
  return 0
}

# ─────────────────────────────────────────────────────────────────────────────
# ПРИЗНАК «ПРОКСИ МОДУЛЕЙ GO НЕДОСТУПЕН» (#949)
#
# Наблюдалось на шарде `e2e nlb` прогона 32529648110:
#
#   github.com/klauspost/compress@v1.19.1: Get "https://storage.googleapis.com/
#   proxy-golang-org-prod/…": net/http: TLS handshake timeout
#   make: *** [Makefile:422: dev-up] Error 2
#
# Шаг объявил это НАШИМ отказом. Классификатор знал ОДНУ форму доказательства
# чужой недоступности — отметку владельца чартов, — а отказ прокси модулей
# приходит из другой ветви сборки и звучит иначе, поэтому попадал в «неопознано»
# и подавался как вердикт о дереве. Цена: прогон блокирует слияние по причине, к
# дереву отношения не имеющей, а разбирающий ищет несуществующий дефект. В том
# прогоне остальные четыре шарда поднялись на том же дереве.
#
# ─── ПОЧЕМУ ЗДЕСЬ ПОНИЖЕНИЕ ЗАКОННО, А У ПРИЗНАКА KIND НИЖЕ — НЕТ ───────────
#
# Разница не в доверии к выводу, а в том, СКОЛЬКО НЕЗАВИСИМЫХ ФАКТОВ в нём
# прочитано. У kind их один, записанный дважды: «кластер не создан» и «узел не
# дошёл до цели» — одно и то же событие, и ровно та же фраза выйдет, если МЫ
# запиним образ узла, несовместимый с ядром.
#
# Здесь фактов три, и они разной природы:
#
#   1. ЧЕЙ хост — из ЗАКРЫТОГО перечня узлов, которыми мы не управляем и адрес
#      которых не наш. Не «похоже на сеть», а поимённо;
#   2. КАКОГО РОДА отказ — ТРАНСПОРТНЫЙ (рукопожатие TLS, сброс соединения,
#      таймаут ввода-вывода), а не содержательный;
#   3. ВЕТО СОДЕРЖАТЕЛЬНОГО ОТКАЗА. Наши собственные ошибки в этой же области —
#      опечатка в пути модуля, несуществующая версия, разошедшаяся контрольная
#      сумма — дают ОТВЕТ ПО СУЩЕСТВУ (404, 410, unknown revision, checksum
#      mismatch), а не таймаут рукопожатия. Любая такая строка где угодно в
#      выводе ЗАПРЕЩАЕТ понижение: тогда в прогоне есть находка о дереве, и
#      снимать с неё цвет нельзя.
#
# Одного первого признака мало — та же фраза о недостижимости выходит на опечатке
# в адресе, и это НАША поломка: повтором не лечится и находкой быть не
# перестаёт. Поэтому требуются оба, и НА ОДНОЙ СТРОКЕ: сообщение Go несёт адрес
# и причину вместе by construction, а раздельный поиск склеил бы сетевой шум из
# одной части вывода с нашим отказом из другой.
GO_PROXY_HOSTS='proxy\.golang\.org|sum\.golang\.org|proxy-golang-org-prod'
GO_TRANSPORT_FAULTS='TLS handshake timeout|connection reset|i/o timeout'
# Содержательные отказы — НАШИ. Перечень закрыт и назван поимённо: «что-нибудь
# похожее на ошибку» веткой быть не может, иначе вето срабатывало бы на прозе.
GO_OUR_FAULTS='unknown revision|invalid version|checksum mismatch|SECURITY ERROR|unrecognized import path|missing go\.sum entry|410 Gone|404 Not Found'

go_module_proxy_unreachable() {
  [ -s "$STAND_LOG" ] || return 1
  # Вето идёт ПЕРВЫМ: находка о дереве важнее любого сетевого шума рядом с ней.
  grep -qE "$GO_OUR_FAULTS" "$STAND_LOG" && return 1
  grep -qE "($GO_PROXY_HOSTS).*($GO_TRANSPORT_FAULTS)" "$STAND_LOG" || return 1
  return 0
}

host_facts() {
  echo "    --- факты хоста (для адъюдикации, не вердикт) ---"
  echo "    ядро:    $(uname -r 2>/dev/null || echo '?')"
  echo "    cgroup:  $(docker info --format '{{.CgroupDriver}} v{{.CgroupVersion}}' 2>/dev/null || echo '?')"
  echo "    память:  $(free -h 2>/dev/null | awk '/^Mem:/{print $2" всего, "$7" доступно"}' || echo '?')"
  echo "    диск /:  $(df -h / 2>/dev/null | awk 'NR==2{print $4" свободно"}' || echo '?')"
}

# Отметки нет — известные формы чужой причины не доказаны. Красное остаётся
# красным дословно как прежде: послабление выдаётся под доказательство, а не
# под его отсутствие.
# ТРЕТЬЯ КАТЕГОРИЯ — ОДНИМ ВЫВОДОМ НА ВСЕ ФОРМЫ ДОКАЗАТЕЛЬСТВА. Форм две
# (отметка владельца чартов и отказ прокси модулей), а печать, флаг и перепись у
# них общие: две копии этого блока разошлись бы молча — ровно так и разошлись
# четыре копии развилки подъёма, из-за которых этот скрипт заведён.
unmet_outcome() { # <причина одной строкой> <предмет>
  local detail="$1" subject="$2"
  echo "категория: НЕ ВЫПОЛНИЛОСЬ — УСЛОВИЕ НЕ СОЗДАНО"
  echo "    $detail"
  echo "    Это ТРЕТЬЯ категория исхода: не зелёное и не красное. Дефекта продукта"
  echo "    здесь НЕ показано, и вердикта нет НИ У ОДНОЙ проверки этой работы."
  echo "    Прогон повторяется, а не разбирается как находка. Предмет — $subject."

  # Флаг — единственное, чем шаги ниже узнают, что стенда нет. Без него они
  # исполнятся на мёртвом кластере и покраснеют «нет отчётов», то есть чужая
  # недоступность снова прочитается как дефект продукта.
  [ -n "${GITHUB_ENV:-}" ]    && echo "STAND_PRECONDITION_UNMET=1" >> "$GITHUB_ENV"
  [ -n "${GITHUB_OUTPUT:-}" ] && echo "category=unmet" >> "$GITHUB_OUTPUT"

  summary "### $LABEL — НЕ ВЫПОЛНИЛОСЬ (условие не создано)"
  summary ""
  summary "$detail"
  summary ""
  summary "Это **третья категория** исхода: не зелёное и не красное. Вердикта нет ни у одной"
  summary "проверки этой работы — «ноль красных» здесь означает «ничего не проверено», а не"
  summary "«замечаний нет». Дефекта продукта не показано; прогон повторяется, а не"
  summary "разбирается как находка. Предмет — $subject."
  census 0 0 1

  # Аннотация — единственное, что доезжает до списка проверок запроса на слияние.
  # `::warning`, а не `::error`: красная аннотация рядом с зелёной проверкой
  # читалась бы как «упало и почему-то пропустили».
  echo "::warning title=НЕ ВЫПОЛНИЛОСЬ (условие не создано)::$LABEL не поднялся: $detail. Вердикта нет ни у одной проверки этой работы — это не «продукт сломан». Прогон повторяется. Предмет — $subject."
  return 0
}

if [ ! -f "$MARK" ]; then
  # ВТОРАЯ ФОРМА ДОКАЗАТЕЛЬСТВА (#949): прокси модулей Go недостижим
  # транспортно, и содержательного отказа в выводе нет. Разбор — над
  # `go_module_proxy_unreachable`.
  if go_module_proxy_unreachable; then
    unmet_outcome "прокси модулей Go не ответил транспортно (рукопожатие TLS, сброс соединения либо таймаут ввода-вывода) — сборка не дошла до нашего кода" "kacho#949"
    exit 0
  fi

  # ЗАЯВЛЕНИЕ НЕ ШИРЕ ДОКАЗАННОГО. Прежняя редакция говорила «это НАШ отказ»,
  # опираясь на отсутствие ОДНОЙ известной формы чужой причины. Из «источник
  # чартов не признан недоступным» не следует «виновато дерево»: это вывод шире
  # посылки, и он посылает читателя искать дефект там, где его может не быть.
  if host_cannot_host_kind; then
    echo "категория: КРАСНОЕ — подъём сорвался; ПРИЧИНА НАЗВАНА: ранер не поднял узел kind"
    echo "    kind не дождался, пока контейнер узла дойдёт до многопользовательской цели,"
    echo "    и кластер не был создан ВОВСЕ. Значит ни один наш чарт, образ и миграция"
    echo "    не исполнялись: по этому отказу дерево разбирать НЕ НАДО."
    echo "    Категория остаётся КРАСНОЙ — не потому, что вина наша, а потому, что"
    echo "    признак прочитан из вывода судимой команды и независимым наблюдателем"
    echo "    не подтверждён. Разбор — в шапке этого скрипта."
    host_facts
    summary "### $LABEL — КРАСНОЕ (причина названа: ранер не поднял узел kind)"
    summary ""
    summary "kind не дождался многопользовательской цели в контейнере узла; кластер не создан"
    summary "вовсе, поэтому ни один наш чарт, образ и миграция не исполнялись — **вердикта о"
    summary "продукте здесь нет**. Категория остаётся красной: признак прочитан из вывода"
    summary "судимой команды и независимым наблюдателем не подтверждён."
    census 0 1 0
    [ -n "${GITHUB_OUTPUT:-}" ] && echo "category=red" >> "$GITHUB_OUTPUT"
    echo "::error title=Стенд не поднялся — ранер не поднял узел kind::$LABEL: kind не дождался многопользовательской цели в контейнере узла (код $rc), кластер не создан вовсе. Вердикта о продукте нет; разбирать дерево по этому отказу не надо."
    exit "$rc"
  fi

  echo "категория: КРАСНОЕ — подъём сорвался, и известные формы чужой причины НЕ доказаны"
  echo "    доказательства недоступности постороннего источника чартов нет"
  echo "    (отметки $MARK не существует); признака «ранер не поднял узел kind» в выводе"
  echo "    тоже нет. Причина названа выводом выше."
  host_facts
  summary "### $LABEL — КРАСНОЕ"
  summary ""
  summary "Подъём сорвался (код $rc), и ни одна известная форма чужой причины не доказана:"
  summary "отметки недоступности источника чартов нет, признака «ранер не поднял узел kind»"
  summary "в выводе тоже нет. Причина — в журнале работы."
  census 0 1 0
  [ -n "${GITHUB_OUTPUT:-}" ] && echo "category=red" >> "$GITHUB_OUTPUT"
  echo "::error title=Стенд не поднялся::$LABEL: подъём сорвался (код $rc), и известные формы чужой причины не доказаны. Причина названа выводом выше."
  exit "$rc"
fi

# Отметка есть — причина ЧУЖАЯ и НАБЛЮДЁННАЯ. Третья категория.
detail="$(cat "$MARK" 2>/dev/null)"
[ -n "$detail" ] || detail="источник чартов не ответил (адрес не извлёкся)"

unmet_outcome "$detail" "kacho#655, снятие зависимости — kacho#2256"
exit 0
